        wspd.push_back(h.wspd);
        wdir.push_back(h.wdir);
    }
    double checksum = SimulateYear(tdb, tdp, pb, wspd, wdir);
    std::printf("%zu hours, checksum %.9f\n", hours.size(), checksum);
    return 0;
}

{
    constexpr int itmax(100);
    double newW;
    double W;
    double ResultX = 0.0;
    double WBT;
    double error;
    double X1 = 0.0;
    double Y1 = 0.0;
    double Wstar;
    double PSatstar;
    int icvg = 0;

    W = dW;
    if (W < 0.0) {
        W = 1.0e-5;
    }
    double const tBoil = PsyTsatFnPb(Patm);
    WBT = TDB;
    for (int iter = 1; iter <= itmax; ++iter) {
        if (WBT >= (tBoil - 0.09)) {
            WBT = tBoil - 0.1;
        }
        PSatstar = PsyPsatFnTemp(WBT);
        Wstar = 0.62198 * PSatstar / (Patm - PSatstar);
        if (WBT >= 0.0) {
            newW = ((2501.0 - 2.326 * WBT) * Wstar - 1.006 * (TDB - WBT)) / (2501.0 + 1.86 * TDB - 4.186 * WBT);
        } else {
            newW = ((2830.0 - 0.24 * WBT) * Wstar - 1.006 * (TDB - WBT)) / (2830.0 + 1.86 * TDB - 2.1 * WBT);
        }
        error = W - newW;
        Iterate(ResultX, iconvTol, WBT, error, X1, Y1, iter, icvg);
        WBT = ResultX;
        if (icvg == 1) {
            break;
        }
    }
    double TWB = WBT;
    if (TWB > TDB) {
        TWB = TDB;
    }
    return TWB;
}

